.gf-premium :is(h1,h2){letter-spacing:0}.gf-premium strong{font-family:inherit;font-weight:700;color:inherit}.gh-model-stage{max-width:772px}#nawierzchnie h2{font-size:44px}@media(max-width:760px){#nawierzchnie h2{font-size:30px}}
/* GF shared wide product presentation v3 */
.gh-model-stage:has([data-model-media="o1"]),.gh-model-stage:has([data-model-media="p1"]){width:100%;max-width:none!important;height:auto!important;min-height:0;aspect-ratio:16/9;align-self:center}
.gh-model-stage :is([data-model-media="o1"],[data-model-media="p1"]){width:100%;height:100%!important;overflow:visible;background:transparent;border-radius:0}
.gh-model-stage :is([data-model-media="o1"],[data-model-media="p1"]) .gh-media-poster{display:block;width:100%;height:100%!important;object-fit:contain}
@media(min-width:761px){.gh-hero-grid:has([data-model-media="o1"]),.gh-hero-grid:has([data-model-media="p1"]){grid-template-columns:minmax(300px,38%) minmax(0,1fr)}}
